pub fn by_id(protocol_id: u32) -> Option<&'static ParticleTypeDef> {
    PARTICLE_TYPES
        .binary_search_by_key(&protocol_id, |e| e.id)
        .ok()
        .map(|idx| &PARTICLE_TYPES[idx])
}

pub fn by_key(key: &str) -> Option<&'static ParticleTypeDef> {
    let full = key.strip_prefix("minecraft:").unwrap_or(key);
    PARTICLE_TYPES
        .iter()
        .find(|e| e.key.strip_prefix("minecraft:").unwrap_or(e.key) == full)
}
